'use strict';
let TransferThreadIndex=null;
async function ensureTransferThreads(){if(!TransferThreadIndex)TransferThreadIndex=await load('transfer-threads/index.json');return TransferThreadIndex}
function transferThreadControls(){return `<section class="transfer-thread-picker"><div><b>이적설의 시작부터 따라가기</b><p>선수를 고르면 현재 날짜까지 나온 보도만 모아 볼 수 있습니다. 확정된 이적 결과를 앞당겨 표시하지 않습니다.</p></div><button class="text-button" id="chooseTransferThread">선수별 보도 흐름 찾기 ↗</button></section>`}
async function chooseTransferThread(){let data=await ensureTransferThreads(),known=data.players.filter(p=>p.first<=state.date);info('선수별 이적 보도 흐름',`<p class="note">${state.date}까지 첫 보도가 확인된 선수입니다. 기사 제목에서 확인한 선수명으로 묶었으며, 같은 행선지를 뜻하거나 이적의 진위를 판정한 목록은 아닙니다.</p><label class="archive-search"><input id="threadPlayerSearch" type="search" placeholder="선수 이름 검색" aria-label="이적 보도 선수 검색"></label><div id="threadPlayerResults">${threadPlayerResults(known,'')}</div>`);$('#threadPlayerSearch').addEventListener('input',e=>$('#threadPlayerResults').innerHTML=threadPlayerResults(known,e.target.value))}
function threadPlayerResults(players,q){return players.filter(p=>p.name.includes(q)).slice(0,100).map(p=>`<button class="thread-player" data-open-thread="${p.id}"><b>${esc(p.name)}</b><small>${p.first} 첫 수록 보도</small></button>`).join('')||'<p class="note">현재 날짜까지 이 이름으로 묶인 보도가 없습니다.</p>'}
async function openTransferThread(id){const index=await ensureTransferThreads(),p=index.players.find(p=>p.id===id);if(!p)return;const shard=await load('transfer-threads/part-'+String(p.shard).padStart(2,'0')+'.json'),reports=(shard[id]||[]).filter(r=>r.date<=state.date);info(esc(p.name)+' · 이 날짜까지의 보도',`<p class="note">기준일 ${state.date}. 이전 기사들은 이 별도 흐름에서만 보이며, 당일 신문 목록과 섞지 않습니다. 보도와 선수·구단의 확정 발표는 구분해서 읽어 주세요. 원문은 이후 수정됐을 수 있습니다.</p><div class="transfer-thread">${reports.slice(-150).map(r=>`<article><time>${r.date}</time><span>${esc(r.category)} · ${esc(r.publisher)}</span><h3>${esc(r.title)}</h3><button class="text-button" data-goto="${r.date}" data-close-thread>그날로 이동 ↗</button> <a class="source-link" href="${esc(r.source)}" target="_blank" rel="noopener">원문 ↗</a></article>`).join('')}</div>${reports.length>150?'<p class="note">가장 최근 150건을 표시합니다. 날짜를 앞당기면 이전 보도를 볼 수 있습니다.</p>':''}`)}
function publicationEvidenceHTML(s){const edited=s.sourceModifiedAt&&s.sourceModifiedAt.slice(0,10)>s.date;return `<section class="publication-evidence"><h3>발행일과 판본 확인</h3><dl><dt>발행</dt><dd>${esc(reportTime(s))}</dd><dt>원문의 수정 메타데이터</dt><dd>${esc(s.sourceModifiedAt||'별도 시각 미확인')}</dd><dt>발행 근거</dt><dd>${esc(s.publicationEvidence||'발행사 날짜 표기')}</dd></dl><p>${edited?'후대 수정 날짜가 있는 원문입니다. 현재 원문의 모든 문장이 그날 공개됐다고 볼 수 없습니다.':'발행일 확인과 발행 당시 초판 본문 보존은 별개입니다. 이 항목의 초판 전체를 보존했다는 뜻은 아닙니다.'}</p></section>`}
document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;if(b.id==='chooseTransferThread')chooseTransferThread().catch(e=>toast(e.message));if(b.dataset.openThread)openTransferThread(b.dataset.openThread).catch(e=>toast(e.message));if(b.hasAttribute('data-close-thread'))$('#infoModal').close()});
